head.b:skin:
/* ==== 0. TOKENS (copied from approved design) ==== */
:root{
  --c-cream:#FAF6EC; --c-cream-2:#F2EAD8; --c-ink:#1C1810;
  --c-ink-soft:rgba(28,24,16,.7); --c-ink-faint:rgba(28,24,16,.45);
  --c-forest:#1E3626; --c-forest-2:#142519; --c-forest-tint:#2C4736;
  --c-mango:#E39A2E; --c-mango-deep:#C1701F; --c-mango-pale:#F3C876; --c-gold:#B8912E;
  --c-white:#FFFFFF; --c-line:rgba(28,24,16,.12); --c-line-on-dark:rgba(250,246,236,.16);
  --font-display:"Fraunces",Georgia,"Times New Roman",serif;
  --font-body:"Inter",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
  --container:1280px; --container-narrow:820px;
  --gutter:clamp(1.25rem,4vw,3.5rem);
  --section-pad:clamp(4rem,9vw,9rem);
  --radius-sm:4px; --radius-md:10px;
  --ease:cubic-bezier(.22,.61,.36,1);
  --dur-fast:.3s; --dur-med:.6s; --dur-slow:1s;
}
@media (prefers-reduced-motion:reduce){ :root{ --dur-fast:0s; --dur-med:0s; --dur-slow:0s; } }

/* ==== 1. RESET & BASE ==== */
*,*::before,*::after{ box-sizing:border-box; }
html{ scroll-behavior:smooth; }
@media (prefers-reduced-motion:reduce){ html{ scroll-behavior:auto; } }
body{ margin:0; background:var(--c-cream); color:var(--c-ink); font-family:var(--font-body); font-size:16px; line-height:1.6; -webkit-font-smoothing:antialiased; overflow-x:hidden; }
img,svg,video{ max-width:100%; display:block; height:auto; }
a{ color:inherit; text-decoration:none; }
ul{ margin:0; padding:0; list-style:none; }
button{ font-family:inherit; cursor:pointer; }
input,textarea,select{ font-family:inherit; font-size:1rem; max-width:100%; }
h1,h2,h3,h4{ font-family:var(--font-display); font-weight:500; line-height:1.08; margin:0 0 .5em; letter-spacing:-.01em; }
p{ margin:0 0 1em; }
:focus-visible{ outline:2px solid var(--c-mango); outline-offset:3px; }
.skip-link{ position:absolute; left:-999px; top:0; z-index:10000; background:var(--c-forest); color:var(--c-cream); padding:1em 1.4em; border-radius:0 0 var(--radius-sm) 0; }
.skip-link:focus{ left:0; }
.container{ max-width:var(--container); margin-inline:auto; padding-inline:var(--gutter); }
.container--narrow{ max-width:var(--container-narrow); }
.eyebrow{ display:inline-block; font-family:var(--font-body); font-size:.75rem; font-weight:600; letter-spacing:.18em; text-transform:uppercase; color:var(--c-mango-deep); margin-bottom:1.1em; }
.section--dark .eyebrow{ color:var(--c-mango-pale); }
.section-title{ font-size:clamp(2.1rem,4.4vw,3.6rem); max-width:16ch; }
.section-lede{ font-size:clamp(1.05rem,1.6vw,1.25rem); color:var(--c-ink-soft); max-width:52ch; }
/* FIX: intro paragraph was dark-on-dark in Orchard, Process and Harvest. Now light on every dark section. */
.section--dark .section-lede,.section--forest .section-lede,.orchard .section-lede,.process .section-lede,.harvest .section-lede{ color:rgba(250,246,236,.8); }
.orchard .eyebrow,.process .eyebrow,.harvest .eyebrow,.section--forest .eyebrow{ color:var(--c-mango-pale); }
.visually-hidden{ position:absolute; width:1px; height:1px; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); border:0; }

/* ==== 2. BUTTONS ==== */
.btn{ display:inline-flex; align-items:center; justify-content:center; gap:.6em; min-height:44px; max-width:100%; padding:1em 1.9em; border-radius:999px; border:1px solid transparent; font-size:.95rem; font-weight:600; letter-spacing:.01em; line-height:1.3; transition:transform var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease),border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease); white-space:nowrap; }
.btn:hover{ transform:translateY(-2px); }
.btn--primary{ background:var(--c-mango); color:var(--c-forest-2); }
.btn--primary:hover{ background:var(--c-mango-deep); color:var(--c-white); }
.btn--outline{ border-color:currentColor; color:inherit; background:transparent; }
.btn--outline:hover{ background:var(--c-ink); color:var(--c-cream); border-color:var(--c-ink); }
.section--dark .btn--outline,.page-hero .btn--outline,.band--dark .btn--outline{ border-color:rgba(250,246,236,.5); }
.section--dark .btn--outline:hover{ background:var(--c-cream); color:var(--c-forest-2); }
.btn--ghost{ background:transparent; color:inherit; padding-inline:0; border-radius:0; border-bottom:1px solid currentColor; min-height:44px; }
.btn--ghost:hover{ transform:none; opacity:.7; }
.btn--whatsapp,.btn--wa{ background:#1E3626; color:#FAF6EC; }
.btn--whatsapp:hover,.btn--wa:hover{ background:#12241A; }
.band--dark .btn--wa{ background:var(--c-cream); color:var(--c-forest-2); }
.btn--sm{ padding:.7em 1.3em; font-size:.85rem; }
@media (max-width:420px){ .btn{ white-space:normal; text-align:center; } .mango-card-footer .btn--sm{ padding-inline:1.05em; } }

/* ==== 3. HEADER / NAV ==== */
.site-header{ position:fixed; top:0; left:0; right:0; z-index:500; padding-block:1.5rem; transition:padding var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease),box-shadow var(--dur-fast) var(--ease); }
.site-header::before{ content:""; position:absolute; inset:0; background:linear-gradient(to bottom,rgba(20,37,25,.55),transparent); opacity:1; transition:opacity var(--dur-fast) var(--ease); pointer-events:none; z-index:-1; }
.site-header.is-scrolled{ padding-block:.85rem; background:rgba(250,246,236,.92); -webkit-backdrop-filter:blur(10px); backdrop-filter:blur(10px); box-shadow:0 1px 0 var(--c-line); }
.site-header.is-scrolled::before{ opacity:0; }
.site-header .container{ display:flex; align-items:center; justify-content:space-between; gap:1.5rem; }
.site-branding{ display:flex; align-items:center; min-width:0; }
.site-logo-link{ display:inline-flex; align-items:center; gap:.6rem; min-height:44px; }
.site-title{ font-family:var(--font-display); font-size:1.05rem; letter-spacing:.04em; text-transform:uppercase; color:var(--c-cream); transition:color var(--dur-fast) var(--ease); }
.site-header.is-scrolled .site-title{ color:var(--c-ink); }
.primary-nav{ display:none; }
@media (min-width:900px){ .primary-nav{ display:block; } }
.primary-nav ul{ display:flex; gap:2.1rem; }
.primary-nav a{ font-size:.88rem; font-weight:500; color:var(--c-cream); position:relative; padding-block:.7em; transition:color var(--dur-fast) var(--ease); }
.site-header.is-scrolled .primary-nav a{ color:var(--c-ink-soft); }
.primary-nav a::after{ content:""; position:absolute; left:0; bottom:.4em; width:0; height:1px; background:currentColor; transition:width var(--dur-fast) var(--ease); }
.primary-nav a:hover::after,.primary-nav a:focus-visible::after{ width:100%; }
.header-actions{ display:flex; align-items:center; gap:1rem; }
.header-actions .btn{ display:none; }
@media (min-width:700px){ .header-actions .btn{ display:inline-flex; } }
.menu-toggle{ display:inline-flex; flex-direction:column; justify-content:center; gap:5px; width:44px; height:44px; background:transparent; border:1px solid var(--c-line-on-dark); border-radius:50%; padding:0; }
@media (min-width:900px){ .menu-toggle{ display:none; } }
.menu-toggle span{ width:16px; height:1px; margin-inline:auto; background:var(--c-cream); transition:transform var(--dur-fast) var(--ease),opacity var(--dur-fast) var(--ease); }
.site-header.is-scrolled .menu-toggle{ border-color:var(--c-line); }
.site-header.is-scrolled .menu-toggle span{ background:var(--c-ink); }
.menu-toggle[aria-expanded="true"] span:nth-child(1){ transform:translateY(6px) rotate(45deg); }
.menu-toggle[aria-expanded="true"] span:nth-child(2){ opacity:0; }
.menu-toggle[aria-expanded="true"] span:nth-child(3){ transform:translateY(-6px) rotate(-45deg); }
.mobile-nav{ position:fixed; inset:0; background:var(--c-forest-2); z-index:490; display:flex; flex-direction:column; justify-content:center; padding:6rem var(--gutter) 3rem; transform:translateY(-100%); visibility:hidden; transition:transform var(--dur-med) var(--ease),visibility 0s linear var(--dur-med); overflow-y:auto; }
.mobile-nav.is-open{ transform:translateY(0); visibility:visible; transition:transform var(--dur-med) var(--ease),visibility 0s; }
.mobile-nav{ color:var(--c-cream); }
.mobile-nav .btn--outline{ border-color:rgba(250,246,236,.5); }
.mobile-nav .btn--outline:hover{ background:var(--c-cream); color:var(--c-forest-2); border-color:var(--c-cream); }
.mobile-nav ul{ display:flex; flex-direction:column; gap:1.1rem; margin-bottom:2.5rem; }
.mobile-nav nav a{ font-family:var(--font-display); font-size:2rem; color:var(--c-cream); }
.mobile-nav .header-actions{ flex-direction:column; align-items:flex-start; gap:1rem; }
.mobile-nav .header-actions .btn{ display:inline-flex; }

/* ==== 4. HERO ==== */
.hero{ position:relative; min-height:100svh; display:flex; flex-direction:column; justify-content:flex-end; overflow:hidden; background:var(--c-forest-2); color:var(--c-cream); }
.hero-media{ position:absolute; inset:0; z-index:0; }
.hero-media img{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; transform:scale(1.08); transition:transform 1.6s var(--ease); }
.hero.is-loaded .hero-media img{ transform:scale(1); }
.hero-media::after{ content:""; position:absolute; inset:0; background:linear-gradient(180deg,rgba(18,36,26,.35) 0%,rgba(18,36,26,.15) 40%,rgba(18,36,26,.85) 100%); }
.hero-content{ position:relative; z-index:2; padding:0 var(--gutter) clamp(5.5rem,10vw,8rem); max-width:var(--container); margin-inline:auto; width:100%; }
.hero-eyebrow{ font-size:.8rem; letter-spacing:.22em; text-transform:uppercase; color:var(--c-mango-pale); margin-bottom:1.2rem; opacity:0; transform:translateY(14px); }
.hero-title{ font-size:clamp(2.6rem,7.2vw,5.6rem); max-width:16ch; color:var(--c-white); opacity:0; transform:translateY(24px); }
.hero-sub{ font-size:clamp(1.05rem,2vw,1.35rem); color:rgba(250,246,236,.82); max-width:44ch; margin-top:1rem; margin-bottom:2.4rem; opacity:0; transform:translateY(24px); }
.hero-ctas{ display:flex; flex-wrap:wrap; gap:1rem; opacity:0; transform:translateY(24px); }
.hero.is-loaded .hero-eyebrow,.hero.is-loaded .hero-title,.hero.is-loaded .hero-sub,.hero.is-loaded .hero-ctas{ opacity:1; transform:translateY(0); transition:opacity var(--dur-slow) var(--ease),transform var(--dur-slow) var(--ease); }
.hero.is-loaded .hero-title{ transition-delay:.1s; }
.hero.is-loaded .hero-sub{ transition-delay:.22s; }
.hero.is-loaded .hero-ctas{ transition-delay:.34s; }
/* no-JS safety: show hero text if scripts never run */
html:not(.js) .hero-eyebrow,html:not(.js) .hero-title,html:not(.js) .hero-sub,html:not(.js) .hero-ctas{ opacity:1; transform:none; }
html:not(.js) .hero-media img{ transform:none; }
.scroll-cue{ position:absolute; bottom:1.6rem; left:50%; transform:translateX(-50%); z-index:2; display:flex; flex-direction:column; align-items:center; gap:.6rem; color:rgba(250,246,236,.7); font-size:.68rem; letter-spacing:.18em; text-transform:uppercase; }
.scroll-cue-line{ width:1px; height:34px; background:rgba(250,246,236,.4); overflow:hidden; position:relative; }
.scroll-cue-line::after{ content:""; position:absolute; top:-100%; left:0; width:100%; height:100%; background:var(--c-mango-pale); animation:scrollcue 2.2s var(--ease) infinite; }
@keyframes scrollcue{ 0%{ top:-100%; } 60%{ top:100%; } 100%{ top:100%; } }
@media (prefers-reduced-motion:reduce){ .scroll-cue-line::after{ animation:none; top:40%; } }
@media (max-width:480px),(max-height:640px){ .scroll-cue{ display:none; } }

/* ==== 5. SECTIONS & REVEAL ==== */
.section{ padding-block:var(--section-pad); position:relative; }
.section--dark{ background:var(--c-forest-2); color:var(--c-cream); }
.section--tint{ background:var(--c-cream-2); }
.section--forest{ background:var(--c-forest); color:var(--c-cream); }
section[id]{ scroll-margin-top:70px; }
.section-head{ margin-bottom:clamp(2.5rem,6vw,4.5rem); }
.section-head--split{ display:flex; flex-wrap:wrap; justify-content:space-between; align-items:flex-end; gap:2rem; }
.js .reveal{ opacity:0; transform:translateY(36px); transition:opacity var(--dur-slow) var(--ease),transform var(--dur-slow) var(--ease); }
.js .reveal.is-visible{ opacity:1; transform:translateY(0); }
.js .reveal-scale{ opacity:0; transform:scale(1.06); transition:opacity 1.1s var(--ease),transform 1.1s var(--ease); }
.js .reveal-scale.is-visible{ opacity:1; transform:scale(1); }

/* ==== 7. FARM / FOUNDER ==== */
.farm-intro{ background:var(--c-cream); }
.farm-intro-grid{ display:grid; gap:clamp(2rem,6vw,5rem); grid-template-columns:minmax(0,1fr); }
@media (min-width:900px){ .farm-intro-grid{ grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr); align-items:center; } }
.farm-intro-copy p{ font-size:1.05rem; color:var(--c-ink-soft); }
.farm-location-card{ margin:2rem 0 0; padding:1.5rem 1.75rem; border:1px solid var(--c-line); border-radius:var(--radius-md); background:var(--c-white); }
.farm-location-card dt{ font-size:.72rem; letter-spacing:.12em; text-transform:uppercase; color:var(--c-mango-deep); margin-top:1rem; }
.farm-location-card dt:first-child{ margin-top:0; }
.farm-location-card dd{ margin:.2rem 0 0; font-size:1rem; }
.farm-intro-media{ aspect-ratio:4/5; border-radius:var(--radius-md); overflow:hidden; position:relative; }
.farm-intro-media img{ width:100%; height:100%; object-fit:cover; }
.founder{ background:var(--c-cream-2); }
.founder-grid{ display:grid; gap:clamp(2rem,6vw,5rem); grid-template-columns:minmax(0,1fr); }
@media (min-width:900px){ .founder-grid{ grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr); align-items:center; } }
.founder-media{ aspect-ratio:3/4; max-width:380px; border-radius:var(--radius-md); overflow:hidden; position:relative; }
.founder-media img{ width:100%; height:100%; object-fit:cover; }
.founder-copy p{ font-size:1.05rem; color:var(--c-ink-soft); }

/* ==== 8. ORCHARD ==== */
.orchard{ background:var(--c-forest-2); color:var(--c-cream); overflow:hidden; }
.orchard-panels{ display:grid; gap:1.25rem; grid-template-columns:repeat(6,minmax(0,1fr)); margin-top:3rem; }
.orchard-panel{ border-radius:var(--radius-md); overflow:hidden; aspect-ratio:3/4; position:relative; }
.orchard-panel img{ width:100%; height:100%; object-fit:cover; transition:transform 1.2s var(--ease); }
.orchard-panel:hover img{ transform:scale(1.06); }
.orchard-panel--a{ grid-column:span 3; }
.orchard-panel--b{ grid-column:span 2; margin-top:3rem; }
.orchard-panel--c{ grid-column:span 1; }
@media (max-width:700px){
  .orchard-panels{ grid-template-columns:repeat(2,minmax(0,1fr)); }
  .orchard-panel--a{ grid-column:span 2; aspect-ratio:16/10; }
  .orchard-panel--b{ grid-column:span 1; margin-top:0; }
  .orchard-panel--c{ grid-column:span 1; }
}

/* ==== 9. PHILOSOPHY ==== */
.philosophy{ background:var(--c-cream-2); }
.philosophy-grid{ display:grid; gap:2rem; grid-template-columns:repeat(auto-fit,minmax(min(220px,100%),1fr)); margin-top:3rem; }
.philosophy-item{ border-top:1px solid var(--c-line); padding-top:1.5rem; }
.philosophy-item .num{ display:block; font-family:var(--font-display); font-size:1rem; color:var(--c-mango-deep); margin-bottom:.75rem; }
.philosophy-item h3{ font-size:1.25rem; margin-bottom:.5rem; }
.philosophy-item p{ color:var(--c-ink-soft); font-size:.95rem; }

/* ==== 10. MANGO COLLECTION ==== */
.mango-collection{ background:var(--c-cream); }
.mango-scroller{ display:flex; gap:1.5rem; overflow-x:auto; scroll-snap-type:x mandatory; padding-bottom:1.5rem; margin-top:3rem; scrollbar-width:thin; scrollbar-color:var(--c-mango) transparent; -webkit-overflow-scrolling:touch; }
.mango-scroller::-webkit-scrollbar{ height:6px; }
.mango-scroller::-webkit-scrollbar-thumb{ background:var(--c-mango); border-radius:3px; }
.mango-card{ scroll-snap-align:start; flex:0 0 min(78vw,360px); border-radius:var(--radius-md); overflow:hidden; background:var(--c-white); border:1px solid var(--c-line); display:flex; flex-direction:column; }
.mango-card-media{ aspect-ratio:1/1; position:relative; }
.mango-card-media img{ width:100%; height:100%; object-fit:cover; }
.mango-card-status{ position:absolute; top:1rem; left:1rem; background:rgba(250,246,236,.92); color:var(--c-forest-2); font-size:.68rem; letter-spacing:.08em; text-transform:uppercase; padding:.4em .8em; border-radius:999px; font-weight:600; }
.mango-card-body{ padding:1.5rem; display:flex; flex-direction:column; gap:.6rem; flex-grow:1; }
.mango-card-body h3{ font-size:1.5rem; }
.mango-card-tagline{ color:var(--c-mango-deep); font-size:.92rem; font-style:italic; margin-bottom:.3rem; }
.mango-card-meta{ display:flex; flex-wrap:wrap; gap:.5rem 1.2rem; font-size:.78rem; color:var(--c-ink-soft); margin:.4rem 0 1rem; }
.mango-card-meta strong{ display:block; color:var(--c-ink); font-size:.68rem; letter-spacing:.08em; text-transform:uppercase; font-weight:600; }
.mango-card-footer{ margin-top:auto; display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:1rem; padding-top:.5rem; }

/* ==== 12. PROCESS ==== */
.process{ background:var(--c-forest); color:var(--c-cream); }
.process-grid{ display:grid; gap:1px; background:var(--c-line-on-dark); margin-top:3rem; grid-template-columns:repeat(2,minmax(0,1fr)); }
@media (min-width:900px){ .process-grid{ grid-template-columns:repeat(3,minmax(0,1fr)); } }
.process-step{ background:var(--c-forest); padding:2.5rem 2rem; }
.process-step .num{ font-family:var(--font-display); font-size:2.4rem; color:rgba(250,246,236,.28); display:block; margin-bottom:1rem; }
.process-step h3{ font-size:1.15rem; letter-spacing:.04em; text-transform:uppercase; margin-bottom:.6rem; }
.process-step p{ font-size:.9rem; color:rgba(250,246,236,.72); margin:0; }
@media (max-width:420px){ .process-step{ padding:2rem 1.25rem; } }

/* ==== 13. HARVEST ==== */
.harvest{ position:relative; color:var(--c-cream); background:var(--c-forest-2); }
.harvest-media{ position:relative; min-height:60vh; }
.harvest-media img{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.harvest-media::after{ content:""; position:absolute; inset:0; background:linear-gradient(90deg,rgba(18,36,26,.92) 0%,rgba(18,36,26,.5) 55%,rgba(18,36,26,.15) 100%); }
.harvest-content{ position:absolute; inset:0; display:flex; align-items:center; z-index:1; }
.harvest-content .container{ max-width:640px; }

/* ==== 14. WHOLESALE / EXPORT ==== */
.b2b{ background:var(--c-cream-2); }
.b2b-grid{ display:grid; gap:3rem; grid-template-columns:minmax(0,1fr); }
@media (min-width:960px){ .b2b-grid{ grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr); align-items:start; } }
.audience-list{ margin-top:1.5rem; display:flex; flex-wrap:wrap; gap:.6rem; }
.audience-tag{ font-size:.78rem; padding:.5em 1em; border:1px solid var(--c-line); border-radius:999px; color:var(--c-ink-soft); }
.b2b-copy .whatsapp-inline{ margin-top:2rem; }
.export{ background:var(--c-forest-2); color:var(--c-cream); }
.export .audience-tag{ border-color:var(--c-line-on-dark); color:rgba(250,246,236,.75); }

/* ==== 15. FORMS (also used by the Blogger pages: .form, .band) ==== */
.farm-form,.entry-content .form{ background:var(--c-white); border-radius:var(--radius-md); padding:clamp(1.5rem,4vw,2.75rem); border:1px solid var(--c-line); }
.section--dark .farm-form,.section--forest .farm-form,.band--dark .form{ background:rgba(250,246,236,.05); border-color:var(--c-line-on-dark); }
.form-row{ display:grid; gap:1.25rem; grid-template-columns:minmax(0,1fr); margin-bottom:1.25rem; }
@media (min-width:620px){ .form-row--2{ grid-template-columns:repeat(2,minmax(0,1fr)); } }
.field{ display:flex; flex-direction:column; gap:.45rem; min-width:0; }
.field label{ font-size:.78rem; font-weight:600; letter-spacing:.03em; }
.field .required{ color:var(--c-mango-deep); }
.field input,.field select,.field textarea{ width:100%; min-height:44px; border:1px solid var(--c-line); background:var(--c-cream); border-radius:var(--radius-sm); padding:.8em .9em; color:var(--c-ink); transition:border-color var(--dur-fast) var(--ease); }
.section--dark .field input,.section--dark .field select,.section--dark .field textarea,.section--forest .field input,.section--forest .field select,.section--forest .field textarea,.band--dark .field input,.band--dark .field select,.band--dark .field textarea{ background:rgba(250,246,236,.06); border-color:var(--c-line-on-dark); color:var(--c-cream); }
.section--dark .field select option,.section--forest .field select option,.band--dark .field select option{ color:var(--c-ink); }
.field input:focus,.field select:focus,.field textarea:focus{ border-color:var(--c-mango); }
.field textarea{ resize:vertical; min-height:100px; }
.form-footer{ display:flex; align-items:center; gap:1.5rem; flex-wrap:wrap; margin-top:.5rem; }
.form-note{ font-size:.8rem; color:var(--c-ink-faint); margin:0; }
.section--dark .form-note,.section--forest .form-note,.band--dark .form-note{ color:rgba(250,246,236,.55); }
.form-status{ margin-top:1rem; padding:1em 1.25em; border-radius:var(--radius-sm); font-size:.92rem; display:none; }
.form-status.is-success{ display:block; background:rgba(30,54,38,.1); border:1px solid var(--c-forest-tint); }
.section--dark .form-status.is-success,.section--forest .form-status.is-success{ background:rgba(250,246,236,.08); }

/* ==== 16. LOCATION / CONTACT ==== */
.location{ background:var(--c-cream); }
.location-grid{ display:grid; gap:3rem; grid-template-columns:minmax(0,1fr); }
@media (min-width:900px){ .location-grid{ grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr); } }
.location-map{ aspect-ratio:4/3; border-radius:var(--radius-md); overflow:hidden; border:1px solid var(--c-line); background:var(--c-cream-2); }
.location-map iframe{ width:100%; height:100%; border:0; display:block; }
.contact-block{ background:var(--c-forest-2); color:var(--c-cream); border-radius:var(--radius-md); padding:2.5rem; }
@media (max-width:480px){ .contact-block{ padding:1.75rem; } }
.contact-block h3{ font-size:1.4rem; }
.contact-list{ margin:1.5rem 0 0; display:flex; flex-direction:column; gap:1.1rem; }
.contact-list dt{ font-size:.7rem; letter-spacing:.1em; text-transform:uppercase; color:var(--c-mango-pale); }
.contact-list dd{ margin:.25rem 0 0; font-size:1.1rem; overflow-wrap:anywhere; }
.contact-list a:hover{ text-decoration:underline; }

/* ==== 17. FINAL CTA ==== */
.final-cta{ position:relative; min-height:70vh; display:flex; align-items:center; justify-content:center; text-align:center; color:var(--c-white); overflow:hidden; }
.final-cta-media{ position:absolute; inset:0; }
.final-cta-media img{ width:100%; height:100%; object-fit:cover; }
.final-cta-media::after{ content:""; position:absolute; inset:0; background:rgba(18,30,20,.6); }
.final-cta-content{ position:relative; z-index:1; max-width:680px; padding:3rem var(--gutter); }
.final-cta-content h2{ font-size:clamp(2.2rem,5.5vw,4rem); color:var(--c-white); }
.final-cta-content .section-lede{ color:rgba(255,255,255,.85); margin-inline:auto; }
.final-cta-ctas{ display:flex; flex-wrap:wrap; gap:1rem; justify-content:center; margin-top:2rem; }

/* ==== 18. FOOTER ==== */
.site-footer{ background:var(--c-forest-2); color:rgba(250,246,236,.75); padding-block:4rem 2rem; }
.footer-grid{ display:grid; gap:2.5rem; grid-template-columns:minmax(0,1fr); margin-bottom:3rem; }
@media (min-width:760px){ .footer-grid{ grid-template-columns:minmax(0,1.4fr) minmax(0,1fr) minmax(0,1fr); } }
.footer-brand h2{ color:var(--c-white); font-size:1.4rem; margin-bottom:.6rem; }
.footer-brand p{ max-width:34ch; font-size:.92rem; }
.footer-col h3{ font-family:var(--font-body); font-weight:400; line-height:1.6; font-size:.74rem; letter-spacing:.1em; text-transform:uppercase; color:rgba(250,246,236,.5); margin-bottom:1rem; }
.footer-col ul{ display:flex; flex-direction:column; gap:.2rem; }
.footer-col li{ overflow-wrap:anywhere; }
.footer-col a{ display:inline-block; padding-block:.5em; }
.footer-col a:hover{ text-decoration:underline; }
.footer-bottom{ border-top:1px solid var(--c-line-on-dark); padding-top:1.5rem; display:flex; flex-wrap:wrap; justify-content:space-between; gap:1rem; font-size:.8rem; color:rgba(250,246,236,.5); }
.footer-bottom p{ margin:0; }

/* ==== 19. WHATSAPP FLOAT ==== */
.whatsapp-float{ position:fixed; bottom:1.5rem; right:1.5rem; z-index:400; display:inline-flex; align-items:center; justify-content:center; width:58px; height:58px; border-radius:50%; background:#1E3626; color:#FAF6EC; box-shadow:0 8px 24px rgba(18,30,20,.35); transition:transform var(--dur-fast) var(--ease); }
.whatsapp-float:hover{ transform:scale(1.08); }
.whatsapp-float svg{ width:26px; height:26px; }

/* ==== 20. INNER PAGES, POSTS, LISTINGS ==== */
.page-hero{ padding:clamp(8rem,16vw,12rem) var(--gutter) 3rem; background:var(--c-forest-2); color:var(--c-cream); }
.page-hero > .container{ padding-inline:0; }
.page-hero h1{ font-size:clamp(2rem,5vw,3.2rem); max-width:22ch; overflow-wrap:break-word; }
.page-hero .eyebrow{ color:var(--c-mango-pale); }
.crumbs{ font-size:.8rem; letter-spacing:.04em; color:rgba(250,246,236,.65); margin-bottom:1rem; }
.crumbs a{ text-decoration:underline; text-underline-offset:2px; }
.post-meta{ display:flex; flex-wrap:wrap; gap:.6em; align-items:center; margin-top:1rem; font-size:.85rem; color:rgba(250,246,236,.65); }
.entry-content{ padding-block:4rem; overflow-wrap:break-word; }
.entry-content > *{ max-width:min(720px,100%); margin-inline:auto; }
.entry-content > .variety,.entry-content > .grid,.entry-content > .band,.entry-content > table,.entry-content > .form{ max-width:min(960px,100%); }
.entry-content h2{ font-size:1.8rem; margin-top:2em; }
.entry-content h3{ font-size:1.3rem; margin-top:1.6em; }
.entry-content img{ border-radius:var(--radius-md); margin-block:1.5em; }
.entry-content a:not(.btn){ text-decoration:underline; text-underline-offset:2px; color:var(--c-mango-deep); }
.entry-content ul,.entry-content ol{ padding-left:1.3em; margin:0 0 1em; }
.entry-content ul{ list-style:disc; }
.entry-content ol{ list-style:decimal; }
.entry-content li{ margin-bottom:.4em; }
.entry-content blockquote{ margin:1.5em auto; padding:.2em 0 .2em 1.25em; border-left:3px solid var(--c-mango); color:var(--c-ink-soft); font-style:italic; }
.entry-content iframe{ width:100%; border:0; border-radius:var(--radius-md); display:block; }
.entry-content .lede{ font-size:1.2rem; color:var(--c-ink-soft); }
.entry-content .note{ font-size:.85rem; color:var(--c-ink-faint); }
.entry-content table{ width:100%; border-collapse:collapse; margin-block:1.5em; font-size:.95rem; }
.entry-content th,.entry-content td{ text-align:left; padding:.8em 1em; border-bottom:1px solid var(--c-line); }
@media (max-width:600px){ .entry-content table{ font-size:.82rem; } .entry-content th,.entry-content td{ padding:.7em .45em; } }
.entry-content th{ font-size:.72rem; letter-spacing:.1em; text-transform:uppercase; color:var(--c-mango-deep); }
.entry-content details{ border-bottom:1px solid var(--c-line); padding:.2em 0; }
.entry-content summary{ cursor:pointer; font-weight:600; padding:.9em 0; min-height:44px; }
.entry-content .variety{ display:grid; gap:2rem; grid-template-columns:minmax(0,1fr); margin-block:3rem; padding-bottom:3rem; border-bottom:1px solid var(--c-line); }
@media (min-width:800px){ .entry-content .variety{ grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr); align-items:start; } }
.entry-content .variety img{ margin:0; width:100%; aspect-ratio:4/3; object-fit:cover; }
.entry-content .variety h2{ margin-top:0; }
.entry-content .facts{ list-style:none; padding:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:1rem 1.5rem; border-top:1px solid var(--c-line); padding-top:1rem; margin-block:1.25rem; }
.entry-content .facts li{ margin:0; font-size:.95rem; }
.entry-content .facts strong{ display:block; font-size:.68rem; letter-spacing:.1em; text-transform:uppercase; color:var(--c-mango-deep); }
.entry-content .grid{ display:grid; gap:1.25rem; grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr)); margin-block:1.5rem; }
.entry-content .box{ background:var(--c-white); border:1px solid var(--c-line); border-radius:var(--radius-md); padding:1.5rem; }
.entry-content .box h3{ margin-top:0; font-size:1.15rem; }
.entry-content .box p:last-child{ margin-bottom:0; }
.entry-content .tags{ list-style:none; padding:0; display:flex; flex-wrap:wrap; gap:.6rem; }
.entry-content .tags li{ font-size:.78rem; padding:.5em 1em; border:1px solid var(--c-line); border-radius:999px; color:var(--c-ink-soft); margin:0; }
.entry-content .band{ background:var(--c-cream-2); border-radius:var(--radius-md); padding:clamp(1.5rem,4vw,2.75rem); margin-block:3rem; }
.entry-content .band--dark{ background:var(--c-forest-2); color:var(--c-cream); }
.entry-content .band h2{ margin-top:0; }
.entry-content .band .form{ padding:0; border:0; background:transparent; }
.entry-content .band .form h3{ margin-top:0; }
.entry-content .band--dark a:not(.btn){ color:var(--c-mango-pale); }
.entry-content .form button.btn{ margin-top:.5rem; }
.post-tags{ max-width:min(720px,100%); margin:2rem auto 0; display:flex; flex-wrap:wrap; gap:.5rem; }
.post-tags a{ font-size:.78rem; padding:.55em 1em; border:1px solid var(--c-line); border-radius:999px; color:var(--c-ink-soft); }
.post-tags a:hover{ border-color:var(--c-mango-deep); color:var(--c-mango-deep); }
.post-share{ max-width:min(720px,100%); margin:2rem auto 0; display:flex; flex-wrap:wrap; gap:1rem; }
.post-share .btn svg{ width:18px; height:18px; }
.not-found{ padding:clamp(8rem,18vw,14rem) var(--gutter) 6rem; text-align:center; }
.not-found .section-lede{ margin-inline:auto; }
.not-found .final-cta-ctas .btn--outline:hover{ color:var(--c-cream); }
.blog-index{ background:var(--c-cream); }
.blog-grid{ display:grid; gap:2.5rem; grid-template-columns:repeat(auto-fill,minmax(min(300px,100%),1fr)); }
.blog-card{ display:flex; flex-direction:column; }
.blog-card-media{ display:block; aspect-ratio:4/3; border-radius:var(--radius-md); overflow:hidden; position:relative; margin-bottom:1.25rem; background:var(--c-forest-2); }
.blog-card-media img{ width:100%; height:100%; object-fit:cover; transition:transform var(--dur-med) var(--ease); }
.blog-card-media:hover img{ transform:scale(1.05); }
.blog-card-date{ font-size:.72rem; letter-spacing:.1em; text-transform:uppercase; color:var(--c-mango-deep); margin-bottom:.4rem; }
.blog-card-body h2,.blog-card-body h3{ font-size:1.4rem; margin-bottom:.5rem; }
.blog-card-body h2 a:hover,.blog-card-body h3 a:hover{ text-decoration:underline; }
.blog-card-body p{ color:var(--c-ink-soft); font-size:.95rem; }
.blog-pagination{ margin-top:4rem; display:flex; justify-content:center; gap:1rem; flex-wrap:wrap; }
.blog-teaser{ background:var(--c-cream-2); }
.empty-note{ color:var(--c-ink-soft); }

/* ==== Blogger housekeeping ==== */
#Navbar1,.navbar,#b-navbar,.blogger-clickTrap{ display:none!important; }
.widget{ margin:0; }
#blog-main.section{ padding:0; margin:0; }
.blog-section,.blog-section .widget{ margin:0; padding:0; }
.hidden-sprite{ position:absolute; width:0; height:0; overflow:hidden; }

body.script:
//
(function () {
  'use strict';
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* Header turns solid after scrolling */
  var header = document.querySelector('[data-site-header]');
  if (header) {
    var onScroll = function () { header.classList.toggle('is-scrolled', window.scrollY > 40); };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
  }

  /* Mobile menu */
  var toggle = document.querySelector('[data-menu-toggle]');
  var mnav = document.querySelector('[data-mobile-nav]');
  if (toggle && mnav) {
    var setOpen = function (open) {
      mnav.classList.toggle('is-open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
      document.body.style.overflow = open ? 'hidden' : '';
    };
    toggle.addEventListener('click', function () { setOpen(!mnav.classList.contains('is-open')); });
    mnav.querySelectorAll('a').forEach(function (a) { a.addEventListener('click', function () { setOpen(false); }); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { setOpen(false); } });
  }

  /* Hero entrance (zoom + text fade-up) */
  var hero = document.querySelector('[data-hero]');
  if (hero) { requestAnimationFrame(function () { hero.classList.add('is-loaded'); }); }

  /* Scroll reveal */
  var els = document.querySelectorAll('.reveal, .reveal-scale');
  if (els.length) {
    if (reduce || !('IntersectionObserver' in window)) {
      els.forEach(function (el) { el.classList.add('is-visible'); });
    } else {
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) { en.target.classList.add('is-visible'); io.unobserve(en.target); }
        });
      }, { threshold: 0.15, rootMargin: '0px 0px -8% 0px' });
      els.forEach(function (el) { io.observe(el); });
    }
  }

  /* Subtle hero parallax */
  var px = document.querySelector('[data-parallax]');
  if (px && !reduce) {
    var ticking = false;
    window.addEventListener('scroll', function () {
      if (!ticking) {
        window.requestAnimationFrame(function () {
          px.style.transform = 'translateY(' + Math.min(window.scrollY * 0.25, 160) + 'px)';
          ticking = false;
        });
        ticking = true;
      }
    }, { passive: true });
  }

  /* Forms: Blogger cannot receive posts, so every form opens WhatsApp with the details written out */
  var NUMBER = '923144419652';
  document.querySelectorAll('form[data-wa-form]').forEach(function (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (!form.checkValidity()) { form.reportValidity(); return; }
      var lines = ['*' + form.getAttribute('data-wa-form') + '* - Ghulam Hussain Farms', ''];
      form.querySelectorAll('.field').forEach(function (f) {
        var label = f.querySelector('label');
        var ctl = f.querySelector('input, select, textarea');
        if (!label || !ctl) { return; }
        var val = (ctl.value || '').trim();
        if (val) { lines.push(label.textContent.replace(/\s*\*$/, '').trim() + ': ' + val); }
      });
      var url = 'https://wa.me/' + NUMBER + '?text=' + encodeURIComponent(lines.join('\n'));
      var status = form.querySelector('[data-form-status]');
      if (status) {
        status.className = 'form-status is-success';
        status.textContent = 'Opening WhatsApp with your details. Press Send there to complete your inquiry.';
      }
      var w = window.open(url, '_blank');
      if (w) { w.opener = null; } else { window.location.href = url; }
    });
  });
})();
//
